/* ============================================================
   Game simulation — path, towers, waves, combat, rendering
   ============================================================ */

import {
  TOWERS, TOWER_ORDER, TARGET_MODES, ENEMY_TYPES,
  START_CREDITS, START_LIVES, getMap, makeWave, waveReward,
  enemyReward, towerLevel, sellValue, clamp,
} from './data.js';
import {
  buildBackground, drawBaseShield, drawTower, drawTowerShadow, drawRange,
  drawEnemy, drawProjectile, drawParticles, drawEffects, drawAura, drawPreview,
  drawSpawnGlow, getTheme,
} from './art.js';

const TAU = Math.PI * 2;

function angleLerp(a, b, t) {
  let d = ((b - a + Math.PI) % TAU + TAU) % TAU - Math.PI;
  return a + d * Math.min(1, t);
}

function samplePath(points, w, h, per = 18) {
  const src = points.map(p => [p[0] * w, p[1] * h]);
  const out = [];
  for (let i = 0; i < src.length - 1; i++) {
    const p0 = src[Math.max(0, i - 1)];
    const p1 = src[i];
    const p2 = src[i + 1];
    const p3 = src[Math.min(src.length - 1, i + 2)];
    for (let s = 0; s < per; s++) {
      const t = s / per;
      const t2 = t * t;
      const t3 = t2 * t;
      const x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      const y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      out.push([x, y]);
    }
  }
  out.push(src[src.length - 1].slice());
  return out;
}

function pointDistanceToPath(x, y, pts) {
  let best = Infinity;
  for (let i = 0; i < pts.length - 1; i++) {
    const ax = pts[i][0], ay = pts[i][1];
    const bx = pts[i + 1][0], by = pts[i + 1][1];
    const dx = bx - ax, dy = by - ay;
    const l2 = dx * dx + dy * dy || 1;
    let t = ((x - ax) * dx + (y - ay) * dy) / l2;
    t = clamp(t, 0, 1);
    const px = ax + dx * t, py = ay + dy * t;
    const d = (x - px) ** 2 + (y - py) ** 2;
    if (d < best) best = d;
  }
  return Math.sqrt(best);
}

export class Game {
  constructor(canvas, audio, callbacks = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.audio = audio;
    this.callbacks = callbacks;
    this.dpr = 1;
    this.w = 1;
    this.h = 1;
    this.S = 1;
    this.pathPts = [];
    this.pathLen = 1;
    this.bg = null;
    this.time = 0;
    this.realTime = 0;
    this.started = false;
    this.paused = false;
    this.speed = 1;
    this.preview = null;
    this.pendingType = null;
    this.selected = null;
    this.shake = 0;
    this.baseFlash = 0;
    this.dustTimer = 0;
    this.uid = 1;
    this.map = getMap('tatooine');
    this.theme = getTheme(this.map.theme);
    this.reset();
    this.resize(
      canvas.clientWidth || 800,
      canvas.clientHeight || 600,
      Math.min(window.devicePixelRatio || 1, 2),
    );
  }

  setMap(id) {
    const next = getMap(id);
    if (this.map && this.map.id === next.id) return;
    this.map = next;
    this.theme = getTheme(next.theme);
    this.reset();
    if (this.w > 1) this.resize(this.w, this.h, this.dpr);
  }

  reset() {
    const map = this.map || getMap('tatooine');
    this.credits = map.startCredits ?? START_CREDITS;
    this.lives = map.startLives ?? START_LIVES;
    this.waveNumber = 1;
    this.waveActive = false;
    this.spawnQueue = null;
    this.spawnTimer = 0;
    this.waveTotal = 0;
    this.waveSpawned = 0;
    this.enemies = [];
    this.towers = [];
    this.projectiles = [];
    this.particles = [];
    this.effects = [];
    this.kills = 0;
    this.creditsEarned = 0;

function drawWampaBody(ctx, e, time) {
  const p = e.phase || 0;
  const breathe = Math.sin(time * 1.9 + p);
  const stride = Math.sin(time * 3.2 + p);
  const strideB = Math.sin(time * 3.2 + p + Math.PI);
  const armSway = Math.sin(time * 2.2 + p + 0.7);

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  /* --- two heavy feet behind the body ----------------------------- */
  const legs = [
    { hx: -15.0, hy: -8.6, kx: -21.0, ky: -15.0, fx: -18.0, fy: -23.0, s: stride, side: -1 },
    { hx: -15.0, hy: 8.6, kx: -21.0, ky: 15.0, fx: -18.0, fy: 23.0, s: strideB, side: 1 },
  ];
  for (const leg of legs) {
    const swing = leg.s * 1.8;
    ctx.strokeStyle = '#b6ccd8';
    ctx.lineWidth = 13.5;
    ctx.beginPath();
    ctx.moveTo(leg.hx, leg.hy);
    ctx.lineTo(leg.kx + swing * 0.2, leg.ky);
    ctx.stroke();
    ctx.strokeStyle = '#e4f1f7';
    ctx.lineWidth = 9.0;
    ctx.beginPath();
    ctx.moveTo(leg.kx + swing * 0.2, leg.ky);
    ctx.lineTo(leg.fx + swing * 0.55, leg.fy);
    ctx.stroke();
    // broad splayed foot
    const baseX = leg.fx + swing * 0.55;
    const baseY = leg.fy;
    ctx.fillStyle = '#eff9fd';
    ctx.beginPath();
    ctx.ellipse(baseX, baseY, 7.8, 5.6, Math.atan2(baseY - leg.ky, baseX - leg.kx), 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(117, 151, 166, 0.65)';
    ctx.lineWidth = 0.8;
    ctx.stroke();
    // four long black claws
    const toeAng = Math.atan2(baseY - leg.ky, baseX - leg.kx);
    for (let claw = -1.5; claw <= 1.5; claw++) {
      const a = toeAng + claw * 0.28;
      const tx = baseX + Math.cos(a) * 9.6;
      const ty = baseY + Math.sin(a) * 9.6;
      ctx.fillStyle = '#26343c';
      ctx.beginPath();
      ctx.moveTo(baseX + Math.cos(a - 0.14) * 4.0, baseY + Math.sin(a - 0.14) * 4.0);
      ctx.quadraticCurveTo(baseX + Math.cos(a) * 7.6, baseY + Math.sin(a) * 7.6 - 1.0, tx, ty);
      ctx.quadraticCurveTo(baseX + Math.cos(a + 0.1) * 6.2, baseY + Math.sin(a + 0.1) * 6.2, baseX + Math.cos(a + 0.16) * 4.0, baseY + Math.sin(a + 0.16) * 4.0);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = 'rgba(191, 224, 237, 0.45)';
      ctx.lineWidth = 0.5;
      ctx.stroke();
    }
    // shaggy ankle cuff
    for (let i = 0; i < 6; i++) {
      const t = 0.45 + i * 0.08;
      const x = leg.hx + (leg.fx - leg.hx) * t;
      const y = leg.hy + (leg.fy - leg.hy) * t;
      ctx.strokeStyle = i % 2 ? 'rgba(255, 255, 255, 0.85)' : 'rgba(177, 207, 221, 0.7)';
      ctx.lineWidth = 0.9;
      ctx.beginPath();
      ctx.moveTo(x, y + leg.side * 4.0);
      ctx.lineTo(x - 2.2, y + leg.side * 7.2);
      ctx.stroke();
    }
  }

  /* --- giant shaggy torso ----------------------------------------- */
  const bodyGrad = ctx.createLinearGradient(-26, -20, 24, 20);
  bodyGrad.addColorStop(0, '#a9c5d3');
  bodyGrad.addColorStop(0.28, '#f1fafd');
  bodyGrad.addColorStop(0.62, '#d9eaf2');
  bodyGrad.addColorStop(1, '#8fb2c4');
  ctx.fillStyle = bodyGrad;
  ctx.beginPath();
  ctx.moveTo(-28.0, 0);
  ctx.bezierCurveTo(-28.0, -7.5, -24.0, -13.5, -17.0, -16.5);
  ctx.bezierCurveTo(-11.0, -19.5, -5.0, -25.5, 6.0, -26.0);
  ctx.bezierCurveTo(18.0, -26.5, 25.5, -21.5, 28.0, -14.0);
  ctx.bezierCurveTo(29.5, -7.5, 29.5, 7.5, 28.0, 14.0);
  ctx.bezierCurveTo(25.5, 21.5, 18.0, 26.5, 6.0, 26.0);
  ctx.bezierCurveTo(-5.0, 25.5, -11.0, 19.5, -17.0, 16.5);
  ctx.bezierCurveTo(-24.0, 13.5, -28.0, 7.5, -28.0, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(104, 139, 155, 0.75)';
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // layered shoulder and flank fur breaks up the round silhouette
  for (let i = 0; i < 22; i++) {
    const t = i / 21;
    const x = -24.0 + t * 48.0;
    const spread = Math.sin(t * Math.PI) * 0.92;
    for (const side of [-1, 1]) {
      const y = side * (15.5 + spread * 8.0);
      const len = 1.8 + ((i * 5) % 4) * 0.55;
      ctx.strokeStyle = i % 4 === 0 ? 'rgba(255, 255, 255, 0.9)' : i % 3 === 0 ? 'rgba(190, 217, 230, 0.8)' : 'rgba(132, 167, 183, 0.65)';
      ctx.lineWidth = 0.85;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x - 1.0, y + side * len);
      ctx.stroke();
    }
  }
  // dark crease between the shoulder blades
  ctx.strokeStyle = 'rgba(120, 153, 169, 0.32)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(-15.0, 0);
  ctx.quadraticCurveTo(0.0, -1.2, 17.0, 0);
  ctx.stroke();

  // shaggy pelt fringe, long around the shoulders and hips
  for (let i = 0; i < 42; i++) {
    const a = 0.24 + (i / 41) * (TAU - 0.48);
    const bx = Math.cos(a) * 23.8;
    const by = Math.sin(a) * 20.4;
    const len = 1.4 + ((i * 11) % 7) * 0.4;
    ctx.strokeStyle = i % 5 === 0 ? 'rgba(255, 255, 255, 0.95)' : i % 3 === 0 ? 'rgba(199, 224, 235, 0.85)' : 'rgba(143, 176, 192, 0.7)';
    ctx.lineWidth = 0.85;
    ctx.beginPath();
    ctx.moveTo(bx * 0.95, by * 0.95);
    ctx.lineTo(bx + Math.cos(a) * len, by + Math.sin(a) * len);
