/* ---------- original illustrated battlefield previews ---------- */
.map-art-illustration {
  isolation: isolate;
  background: #0a1017;
}
.map-art-illustration::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(4, 9, 15, 0.05) 0%, rgba(4, 9, 15, 0.12) 46%, rgba(4, 9, 15, 0.82) 100%),
    linear-gradient(90deg, rgba(4, 9, 15, 0.28), transparent 42%);
}
.map-art-illustration .map-illustration {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(1.04) contrast(1.04) brightness(0.92);
  transform: scale(1.02);
  transition: transform 0.5s ease, filter 0.35s ease;
}
.map-tile-available:hover .map-art-illustration .map-illustration,
.map-tile-available:focus-visible .map-art-illustration .map-illustration {
  transform: scale(1.075);
  filter: saturate(1.14) contrast(1.06) brightness(1);
}
.map-art-illustration .map-art-tag {
  z-index: 2;
