}
.page-title p { margin: 4px 0 0; font-size: 8px; line-height: 1.4; color: #99adbc; }
.menu-back {
  padding: 5px 8px;
  border: 1px solid rgba(129, 191, 222, 0.2);
  border-radius: 7px;
  background: rgba(10, 18, 28, 0.62);
  color: #a8bdcb;
  font-size: 6.5px;
  font-weight: 900;
  width: 100%;
  margin-top: auto;
  padding-top: 10px;
  opacity: 0.95;
}
.hub-mini-icon {
  display: grid; place-items: center;
  width: 100%; height: 40px;
  border: 1px solid rgba(129, 191, 222, 0.18);
  border-radius: 8px;
  background: radial-gradient(circle at 40% 28%, rgba(125, 214, 245, 0.14), rgba(8, 16, 26, 0.72) 72%);
